-- Real per-lesson content for the 15 Academy courses seeded in 012_academy.sql -- previously
-- "lessons" on the courses table was only ever a bare count; there was no actual title or
-- description stored anywhere for any lesson, of any course. This adds that real content.

CREATE TABLE IF NOT EXISTS chapters (
  id            TEXT PRIMARY KEY,
  course_id     TEXT NOT NULL REFERENCES courses(id) ON DELETE CASCADE,
  number        INTEGER NOT NULL,
  title         TEXT NOT NULL,
  description   TEXT NOT NULL,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (course_id, number)
);

CREATE INDEX IF NOT EXISTS idx_chapters_course_id ON chapters (course_id);

ON CONFLICT (id) DO NOTHING;

-- Total chapters seeded: 73, across 15 courses
